import numpy as np, collections, json
def flood(a,bg=0):
    a=np.array(a); H,W=a.shape; seen=set(); dq=collections.deque()
    for r in range(H):
        for c in (0,W-1):
            if a[r,c]==bg and (r,c) not in seen: seen.add((r,c)); dq.append((r,c))
    for c in range(W):
        for r in (0,H-1):
            if a[r,c]==bg and (r,c) not in seen: seen.add((r,c)); dq.append((r,c))
    while dq:
        y,x=dq.popleft()
        for ny,nx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
            if 0<=ny<H and 0<=nx<W and a[ny][nx]==bg and (ny,nx) not in seen:
                seen.add((ny,nx)); dq.append((ny,nx))
    return seen
def solve(inp,fillmap={3:8,5:4,7:3}):
    ai=np.array(inp); H,W=ai.shape
    se=flood(ai)
    rem={(r,c) for r in range(H) for c in range(W) if ai[r][c]==0 and (r,c) not in se}
    out=[[int(v) for v in row] for row in inp]
    while rem:
        seed=rem.pop(); stk=[seed]; comp=[seed]
        while stk:
            y,x=stk.pop()
            for ny,nx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
                if (ny,nx) in rem: rem.discard((ny,nx)); stk.append((ny,nx)); comp.append((ny,nx))
        rs=[r for r,c in comp]; cs=[c for r,c in comp]
        bh=max(rs)-min(rs)+1; bw=max(cs)-min(cs)+1
        f=fillmap.get(max(bh,bw))
        if f is None: raise AssertionError('unknown box',(bh,bw))
        for r,c in comp: out[r][c]=f
    return out
